"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["47174"],{55801(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.modalidade_selecionada.composicao_origem_indevida","status":422,"titulo":"C\xf3digo de origem s\xf3 se aplica \xe0 composi\xe7\xe3o RETIRADA_DE_OUTRA_MODALIDADE"},"descricao":{"codigo":"uniplus.selecao.modalidade_selecionada.composicao_origem_indevida","requisitos":[],"oQueAconteceu":["Uma modalidade selecionada declarou `composicaoOrigemCodigo` sem ter\\n`composicaoVagas: RETIRADA_DE_OUTRA_MODALIDADE`. O c\xf3digo de origem s\xf3 tem sentido quando a\\nmodalidade retira vagas de outra \u2014 nas demais composi\xe7\xf5es (ampla\\nconcorr\xeancia residual, sub-reserva da Lei 12.711, suplemento ao total), a\\nmodalidade tem seu pr\xf3prio quadro, sem depender de outra.","Este \xe9 o par sim\xe9trico de\\n[`composicao_origem_obrigatoria`](/erros/uniplus.selecao.modalidade_selecionada.composicao_origem_obrigatoria):\\na mesma coer\xeancia, olhada do lado oposto \u2014 l\xe1, o campo faltando quando devia\\nestar presente; aqui, presente quando devia faltar. Esta recusa sai junto com as demais recusas da modalidade; corrija todas antes de selecionar de novo.","**`composicaoVagas` e `composicaoOrigemCodigo` n\xe3o v\xeam do corpo do pedido da\\ndefini\xe7\xe3o de distribui\xe7\xe3o de vagas** \u2014 s\xe3o copiados do cadastro de\\nmodalidades de Configura\xe7\xe3o, no momento em que a modalidade \xe9 selecionada.\\nNo cadastro, o c\xf3digo de origem \xe9 informado em `composicaoOrigem`.\\nO pr\xf3prio cadastro j\xe1 impede esta incoer\xeancia na\\nescrita, tanto na cria\xe7\xe3o quanto na atualiza\xe7\xe3o; pela defini\xe7\xe3o de\\ndistribui\xe7\xe3o de vagas, este c\xf3digo s\xf3 aparece se a modalidade estiver\\ngravada no cadastro de um jeito que contorna essa valida\xe7\xe3o.","Este c\xf3digo tamb\xe9m aparece na **retifica\xe7\xe3o em ato \xfanico**: antes de\\ncongelar a vers\xe3o nova, o sistema l\xea as vers\xf5es j\xe1 publicadas do processo,\\ne essa leitura recria cada modalidade selecionada a partir do que foi\\ncongelado \u2014 a mesma cria\xe7\xe3o \xe9 conferida de novo."],"comoResolver":["O campo em excesso n\xe3o est\xe1 no corpo do pedido que voc\xea enviou \u2014 est\xe1 na modalidade\\ncadastrada em Configura\xe7\xe3o. Corrija l\xe1 a composi\xe7\xe3o de vagas ou remova o\\nc\xf3digo de origem indevido, ou investigue como a modalidade foi gravada sem\\nessa coer\xeancia.","Se o erro apareceu na retifica\xe7\xe3o em ato \xfanico, o problema tamb\xe9m n\xe3o est\xe1\\nno que foi enviado agora \u2014 est\xe1 em uma vers\xe3o j\xe1 publicada, que reflete\\numa modalidade j\xe1 incoerente no momento em que foi selecionada."],"ondeAparece":["Defini\xe7\xe3o de distribui\xe7\xe3o de vagas do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Modalidade selecionada"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"e5dad467d85ce0f062b88f68241ad834bc540cf0"}}')}}]);